#[test]fn actual_raw_tree_exempt_inputs_still_feed_only_the_original_unfiltered_global_phases(){let root=root();let configuration=root.join("tools/ci/lint_scopes.toml");std::fs::write(&configuration,initial::configuration(true)).unwrap();let physical=Physical{reads:Mutex::new(BTreeMap::new()),fail_policy:Mutex::new(None)};let inputs=RecordingInputs::new(&physical,5_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=frontend(&root,&inputs,&db);let capture=workspace_capture::capture(&front,&inputs,discovery(&root,&inputs),&configuration).unwrap();let current=snapshot(&front,&db,&inputs,&capture);let before=physical.reads();for policy in POLICIES{current.with_native_raw_tree(&current.tree,policy,|data,_,_|{match policy{Policy::Pool=>{assert!(!data.sites().iter().any(|site|site.rule=="new_pooled"),"generic-exempt pooled declaration does not contribute global facts");assert!(data.sites().iter().any(|site|site.rule=="take_leak"));assert!(data.allow_used().is_empty());},Policy::DeclarationBlock=>{assert!(data.sites().iter().any(|site|site.rule=="two_blocks"&&site.rel=="code/z.dm"));assert!(!data.sites().iter().any(|site|site.rule=="bundle"||site.rule=="backslash_list"));},Policy::Pollers=>assert!(data.sites().iter().any(|site|site.rule=="step_coverage"&&site.rel=="maps/poller.dm")),Policy::ReadBack=>assert!(!data.sites().iter().any(|site|site.rel=="code/selected_handler.dm"),"exempt notice declaration remains authoritative in the old global index"),Policy::DuplicateInputKey|Policy::CapBits=>assert!(!data.sites().iter().any(|site|site.rel=="code/a.dm")),Policy::Interactions=>{assert!(data.sites().is_empty());assert_eq!(data.allow_used().len(),1,"every selected declaration asks ALLOW even with no inherited shadow");},Policy::Cooldown|Policy::Latent=>assert!(data.allow_used().is_empty(),"exempt annotation is never queried"),Policy::OpOrder|Policy::UiActions|Policy::Ownership|Policy::ManualLog|Policy::Sfx|Policy::Requirements|Policy::StringNames|Policy::ConstructorShadow|Policy::LookEffects|Policy::Expiry|Policy::DocSnippets|Policy::Ui=>panic!("these policies use their dedicated fixtures")};Ok(())}).unwrap();}assert_eq!(physical.reads(),before);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);}

